CREATE TABLE public.subscriptions (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'inactive' CHECK(status IN('inactive','active','trialing','past_due','canceled')), current_period_end timestamptz, provider_customer_id text, provider_subscription_id text UNIQUE);
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role; ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY subscription_owner ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_premium(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=_user_id AND status IN('active','trialing') AND current_period_end > now()) $$; REVOKE ALL ON FUNCTION public.is_premium(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_premium(uuid) TO authenticated;
CREATE TABLE public.blocks (blocker_id uuid NOT NULL REFERENCES public.profiles(id), blocked_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
GRANT SELECT,INSERT,DELETE ON public.blocks TO authenticated; GRANT ALL ON public.blocks TO service_role; ALTER TABLE public.blocks ENABLE ROW LEVEL SECURITY; CREATE POLICY blocks_owner ON public.blocks FOR ALL TO authenticated USING(blocker_id=auth.uid()) WITH CHECK(blocker_id=auth.uid());
CREATE FUNCTION public.pair_blocked(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=a AND blocked_id=b) OR (blocker_id=b AND blocked_id=a)) $$; REVOKE ALL ON FUNCTION public.pair_blocked(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.pair_blocked(uuid,uuid) TO authenticated;
CREATE TABLE public.swipes (actor_id uuid NOT NULL REFERENCES public.profiles(id), target_id uuid NOT NULL REFERENCES public.profiles(id), choice text NOT NULL CHECK(choice IN('like','pass','super')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,target_id), CHECK(actor_id<>target_id));
GRANT SELECT ON public.swipes TO authenticated; GRANT ALL ON public.swipes TO service_role; ALTER TABLE public.swipes ENABLE ROW LEVEL SECURITY; CREATE POLICY own_swipes ON public.swipes FOR SELECT TO authenticated USING(actor_id=auth.uid() OR (target_id=auth.uid() AND choice IN('like','super') AND public.is_premium(auth.uid())));
CREATE TABLE public.matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_a uuid NOT NULL REFERENCES public.profiles(id), user_b uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_a,user_b), CHECK(user_a<user_b));
GRANT SELECT ON public.matches TO authenticated; GRANT ALL ON public.matches TO service_role; ALTER TABLE public.matches ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_access_match(_match uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.matches WHERE id=_match AND _user IN(user_a,user_b) AND public.is_verified(user_a) AND public.is_verified(user_b) AND NOT public.pair_blocked(user_a,user_b)) $$; REVOKE ALL ON FUNCTION public.can_access_match(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_access_match(uuid,uuid) TO authenticated;
CREATE POLICY participant_matches ON public.matches FOR SELECT TO authenticated USING(public.can_access_match(id,auth.uid()));
CREATE FUNCTION public.cast_swipe(_target uuid,_choice text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid:=auth.uid(); mid uuid; BEGIN IF actor IS NULL OR actor=_target OR _choice NOT IN('like','pass','super') OR NOT public.is_verified(actor) OR NOT public.is_verified(_target) OR public.pair_blocked(actor,_target) THEN RAISE EXCEPTION 'Both members must be identity-approved and unblocked'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(LEAST(actor,_target)::text||GREATEST(actor,_target)::text,0)); INSERT INTO public.swipes(actor_id,target_id,choice) VALUES(actor,_target,_choice) ON CONFLICT(actor_id,target_id) DO UPDATE SET choice=EXCLUDED.choice,created_at=now(); IF _choice IN('like','super') AND EXISTS(SELECT 1 FROM public.swipes WHERE actor_id=_target AND target_id=actor AND choice IN('like','super')) THEN INSERT INTO public.matches(user_a,user_b) VALUES(LEAST(actor,_target),GREATEST(actor,_target)) ON CONFLICT(user_a,user_b) DO NOTHING; SELECT id INTO mid FROM public.matches WHERE user_a=LEAST(actor,_target) AND user_b=GREATEST(actor,_target); END IF; RETURN mid; END $$;
REVOKE ALL ON FUNCTION public.cast_swipe(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cast_swipe(uuid,text) TO authenticated;
CREATE FUNCTION public.rewind_swipe() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.is_premium(auth.uid()) THEN RAISE EXCEPTION 'Rewind requires premium'; END IF; SELECT target_id INTO target FROM public.swipes WHERE actor_id=auth.uid() AND choice='pass' ORDER BY created_at DESC LIMIT 1; IF target IS NULL THEN RETURN false; END IF; DELETE FROM public.swipes WHERE actor_id=auth.uid() AND target_id=target; RETURN true; END $$; REVOKE ALL ON FUNCTION public.rewind_swipe() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.rewind_swipe() TO authenticated;
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES public.matches(id), sender_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL DEFAULT '' CHECK(char_length(body)<=2000), voice_path text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(char_length(trim(body))>0 OR voice_path IS NOT NULL));
GRANT SELECT,INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role; ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY; CREATE POLICY messages_read ON public.messages FOR SELECT TO authenticated USING(public.can_access_match(match_id,auth.uid())); CREATE POLICY messages_send ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.can_access_match(match_id,auth.uid()) AND (voice_path IS NULL OR (voice_path LIKE auth.uid()::text||'/%' AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='profile-media' AND name=voice_path AND owner_id=auth.uid()::text))));
CREATE INDEX messages_conversation ON public.messages(match_id,created_at);
CREATE TABLE public.reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES public.profiles(id), reported_id uuid NOT NULL REFERENCES public.profiles(id), reason text NOT NULL CHECK(char_length(reason) BETWEEN 3 AND 1000), status text NOT NULL DEFAULT 'open' CHECK(status IN('open','reviewed')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(reporter_id<>reported_id));
GRANT SELECT,INSERT ON public.reports TO authenticated; GRANT UPDATE(status) ON public.reports TO authenticated; GRANT ALL ON public.reports TO service_role; ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY; CREATE POLICY reports_read ON public.reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY reports_insert ON public.reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='open'); CREATE POLICY reports_review ON public.reports FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.photo_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), original_path text NOT NULL, style text NOT NULL CHECK(style IN('sakura','cinematic','manga')), status text NOT NULL DEFAULT 'processing' CHECK(status IN('processing','ready','failed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.photo_jobs TO authenticated; GRANT ALL ON public.photo_jobs TO service_role; ALTER TABLE public.photo_jobs ENABLE ROW LEVEL SECURITY; CREATE POLICY jobs_owner ON public.photo_jobs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profile_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), kind text NOT NULL CHECK(kind IN('anime_photo','video')), path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.profile_media TO authenticated; GRANT ALL ON public.profile_media TO service_role; ALTER TABLE public.profile_media ENABLE ROW LEVEL SECURITY; CREATE POLICY media_read ON public.profile_media FOR SELECT TO authenticated USING(user_id=auth.uid() OR (public.is_verified(auth.uid()) AND public.is_verified(user_id) AND NOT public.pair_blocked(user_id,auth.uid()) AND (kind='anime_photo' OR public.is_premium(auth.uid())))); CREATE POLICY media_delete ON public.profile_media FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE POLICY originals_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='profile-originals' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN('jpg','jpeg','png','webp'));
CREATE POLICY originals_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='profile-originals' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY originals_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='profile-originals' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY member_media_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='profile-media' AND (storage.foldername(name))[1]=auth.uid()::text AND ((lower(storage.extension(name)) IN('mp4','mov') AND public.is_premium(auth.uid()) AND public.is_verified(auth.uid())) OR lower(storage.extension(name)) IN('webm','ogg','m4a')));
CREATE POLICY member_media_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='profile-media' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.profile_media m WHERE m.path=name AND public.is_verified(auth.uid()) AND public.is_verified(m.user_id) AND NOT public.pair_blocked(m.user_id,auth.uid()) AND (m.kind='anime_photo' OR public.is_premium(auth.uid()))) OR EXISTS(SELECT 1 FROM public.messages m WHERE m.voice_path=name AND public.can_access_match(m.match_id,auth.uid()))));
CREATE POLICY member_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='profile-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE TABLE public.community_rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL CHECK(char_length(title) BETWEEN 3 AND 100), anime text NOT NULL CHECK(char_length(anime) BETWEEN 1 AND 150), kind text NOT NULL CHECK(kind IN('watch','club','seasonal','convention')), episode integer NOT NULL DEFAULT 1 CHECK(episode>=1), starts_at timestamptz, streaming_url text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.community_rooms TO authenticated; GRANT ALL ON public.community_rooms TO service_role; ALTER TABLE public.community_rooms ENABLE ROW LEVEL SECURITY; CREATE POLICY rooms_read ON public.community_rooms FOR SELECT TO authenticated USING(true); CREATE POLICY rooms_create ON public.community_rooms FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND public.is_verified(auth.uid())); CREATE POLICY rooms_update ON public.community_rooms FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND public.is_verified(auth.uid()));
CREATE TABLE public.room_members (room_id uuid NOT NULL REFERENCES public.community_rooms(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.room_members TO authenticated; GRANT ALL ON public.room_members TO service_role; ALTER TABLE public.room_members ENABLE ROW LEVEL SECURITY; CREATE POLICY memberships_read ON public.room_members FOR SELECT TO authenticated USING(true); CREATE POLICY memberships_insert ON public.room_members FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_verified(auth.uid())); CREATE POLICY memberships_delete ON public.room_members FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.in_room(_room uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_verified(_user) AND EXISTS(SELECT 1 FROM public.room_members WHERE room_id=_room AND user_id=_user) $$; REVOKE ALL ON FUNCTION public.in_room(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.in_room(uuid,uuid) TO authenticated;
CREATE TABLE public.room_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.community_rooms(id), user_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL CHECK(char_length(trim(body)) BETWEEN 1 AND 2000), spoiler boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.room_messages TO authenticated; GRANT ALL ON public.room_messages TO service_role; ALTER TABLE public.room_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY room_chat_read ON public.room_messages FOR SELECT TO authenticated USING(public.in_room(room_id,auth.uid()) AND NOT public.pair_blocked(user_id,auth.uid())); CREATE POLICY room_chat_insert ON public.room_messages FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.in_room(room_id,auth.uid()));
CREATE TABLE public.bingo_progress (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), cells text[] NOT NULL DEFAULT '{}'); GRANT SELECT,INSERT,UPDATE ON public.bingo_progress TO authenticated; GRANT ALL ON public.bingo_progress TO service_role; ALTER TABLE public.bingo_progress ENABLE ROW LEVEL SECURITY; CREATE POLICY bingo_owner ON public.bingo_progress FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.guard_review_transition() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status<>'pending' OR NEW.status NOT IN('approved','rejected') OR NEW.user_id<>OLD.user_id OR NEW.id_path<>OLD.id_path OR NEW.selfie_path<>OLD.selfie_path THEN RAISE EXCEPTION 'Only a pending submission can be reviewed'; END IF; RETURN NEW; END $$; CREATE TRIGGER guard_identity_review BEFORE UPDATE ON public.identity_submissions FOR EACH ROW EXECUTE FUNCTION public.guard_review_transition();
CREATE FUNCTION public.sync_profile_age() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE dob date; BEGIN SELECT birth_date INTO dob FROM public.account_details WHERE user_id=NEW.id; IF dob IS NOT NULL THEN NEW.age:=date_part('year',age(CURRENT_DATE,dob)); END IF; RETURN NEW; END $$; CREATE TRIGGER sync_profile_age BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.sync_profile_age();
CREATE POLICY compatible_preferences ON public.anime_preferences FOR SELECT TO authenticated USING(public.is_verified(auth.uid()) AND public.is_verified(user_id) AND NOT public.pair_blocked(user_id,auth.uid()));
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='messages') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.messages; END IF; IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='room_messages') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.room_messages; END IF; END $$;